"""Actual header module and complete shipped CSS; isolated navigation fixtures."""
import argparse,json,pathlib,re
from playwright.sync_api import sync_playwright
p=argparse.ArgumentParser();p.add_argument('--engine',required=True);a=p.parse_args()
root=pathlib.Path('vision-talk/pablicus');out=pathlib.Path('results');out.mkdir(exist_ok=True)
html=(root/'index.html').read_text();html=re.sub(r'<script\b[^>]*>.*?</script>','',html,flags=re.S)
html=re.sub(r'<link\b[^>]*>', '', html)
styles=re.findall(r'<link[^>]*href="([^"]+\.css)[^"]*"', (root/'index.html').read_text())
checks=[]
with sync_playwright() as pw:
 browser=getattr(pw,a.engine).launch();page=browser.new_page(viewport={'width':390,'height':844});page.set_default_timeout(10000)
 page.route('**/*',lambda r:r.continue_() if r.request.url.startswith(('blob:','data:')) else r.abort())
 page.set_content(html)
 for name in styles:page.add_style_tag(content=(root/name).read_text())
 page.evaluate("""()=>{window.PablicusAvatarStoriesUI={};window.visits=[];window.routeState={conversationId:'fixture-a'};window.PablicusController={state:()=>routeState};window.PablicusContacts={open:id=>visits.push(id)};document.querySelector('#home').hidden=true;document.querySelector('#app').hidden=false;const rail=document.createElement('div');rail.className='r2FunctionRail';document.querySelector('#composeBox').classList.add('r2Composer');document.querySelector('#composeBox').append(rail);const title=document.querySelector('#chatTitle');title.textContent='Катюша ❤️❤️❤️';title.onclick=()=>PablicusContacts.open(routeState.conversationId);}""")
 page.add_script_tag(content=(root/'glass-ui.js').read_text())
 page.locator('.chatAvatarDock>#chatTitle').wait_for()
 def check(name,ok):
  assert ok,name
  checks.append(name)
 page.wait_for_timeout(260)
 check('back outside menu and available when collapsed',page.locator('#app>#chatBack').is_visible() and page.locator('#chatActionsMenu #chatBack').count()==0)
 back=page.locator('#chatBack').bounding_box();toggle=page.locator('#chatActionsToggle').bounding_box()
 check('back aligned upper left opposite menu',abs(back['y']-toggle['y'])<1 and back['x']<toggle['x'] and back['width']==44)
 page.evaluate("document.querySelector('#chatBack').addEventListener('click',()=>window.backUsed=true)")
 page.locator('#chatBack').click();check('back click retains live button',page.evaluate('backUsed===true'))
 for selector in ['#composeBox','.workspaceEditor','.botComposer']:
  if selector!='#composeBox':page.evaluate('(cls)=>{const n=document.createElement("div");n.className=cls+" r2Composer";document.body.append(n)}',selector[1:])
  check(selector+' has glass background only',page.locator(selector).evaluate('(n)=>{const s=getComputedStyle(n,"::before");return (n.id==="composeBox"?s.content==="none"&&getComputedStyle(n).backgroundColor==="rgba(0, 0, 0, 0)":s.content!=="none"&&s.backdropFilter.includes("blur(16px)")&&s.pointerEvents==="none")&&getComputedStyle(n).filter==="none"}'))
  if selector!='#composeBox':page.locator(selector).evaluate('(n)=>n.remove()')
 check('menu initially collapsed and inert',page.locator('#chatActionsMenu').evaluate('(n)=>n.inert&&getComputedStyle(n).visibility==="hidden"'))
 page.locator('#chatActionsToggle').click();page.wait_for_timeout(260)
 check('menu opens with vertical dots',page.locator('#chatActionsToggle').get_attribute('aria-expanded')=='true' and page.locator('#chatActionsMenu').evaluate('(n)=>!n.inert&&getComputedStyle(n).opacity==="1"') and page.locator('#chatActionsToggle svg').evaluate('(n)=>getComputedStyle(n).transform==="matrix(0, 1, -1, 0, 0, 0)"'))
 check('menu appears below upper-right toggle',page.locator('#chatActionsMenu').bounding_box()['y']>=page.locator('#chatActionsToggle').bounding_box()['y']+44)
 page.locator('#chatActionsToggle').click();page.wait_for_timeout(260)
 check('same button collapses menu',page.locator('#chatActionsMenu').evaluate('(n)=>n.inert&&getComputedStyle(n).visibility==="hidden"'))
 page.locator('#chatActionsToggle').click();page.keyboard.press('Escape');page.wait_for_timeout(260)
 check('escape closes and restores focus',page.locator('#chatActionsToggle').evaluate('(n)=>document.activeElement===n&&n.getAttribute("aria-expanded")==="false"'))
 page.locator('#chatActionsToggle').click();page.locator('#conversationAvatar').click();page.wait_for_timeout(260)
 check('outside press closes menu',page.locator('#chatActionsToggle').get_attribute('aria-expanded')=='false')
 page.evaluate('visits=[]')
 for width,safe in [(390,59),(320,0),(768,24)]:
  page.set_viewport_size({'width':width,'height':844});page.evaluate('(v)=>document.documentElement.style.setProperty("--safe-area-top",v+"px")',safe)
  page.wait_for_timeout(80)
  box=page.locator('#conversationAvatar').bounding_box();title=page.locator('#chatTitle').bounding_box();app=page.locator('#app').bounding_box();stage=page.locator('#app>.stage').bounding_box()
  check(f'{width}: centered round avatar',abs(box['x']+box['width']/2-app['x']-app['width']/2)<2 and abs(box['width']-box['height'])<1 and abs(box['width']-60)<1)
  check(f'{width}: avatar overlaps name pill',3<=box['y']+box['height']-title['y']<=8)
  check(f'{width}: clear safe area and no reserved white header',box['y']>=app['y']+safe+20 and abs(stage['y']-app['y'])<1)
  check(f'{width}: avatar is hit target',page.locator('#conversationAvatar').evaluate('(n)=>{const r=n.getBoundingClientRect();return n.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2))}'))
 page.locator('#chatTitle').click();check('name retains profile handler',page.evaluate("visits.at(-1)==='fixture-a'"))
 page.evaluate("routeState.conversationId='fixture-b';document.querySelector('#chatTitle').textContent='Новое личное имя'")
 page.locator('#chatTitle').click();check('new conversation uses current identity',page.evaluate("visits.at(-1)==='fixture-b'"))
 check('no call controls in chat',page.locator('#app #conversationCallDock,#app #audioCallAction,#app #videoCallAction').count()==0)
 check('identity has no application blur',page.locator('.chatAvatarDock').evaluate('(n)=>[n,document.querySelector("#conversationAvatar")].every(e=>getComputedStyle(e).filter==="none"&&getComputedStyle(e).backdropFilter==="none")'))
 check('name pill has localized glass',page.locator('#chatTitle').evaluate('(n)=>{const s=getComputedStyle(n);return s.backdropFilter.includes("blur(8px)")&&s.backgroundColor!=="rgba(0, 0, 0, 0)"&&s.boxShadow!=="none"}'))
 check('rounded vector chevron',page.locator('#chatTitle').evaluate('(n)=>{const s=getComputedStyle(n,"::after");return s.width==="18px"&&(s.maskImage||s.webkitMaskImage).includes("svg")}'))
 check('one live title' ,page.locator('#chatTitle').count()==1)
 page.locator('#conversationAvatar').click();check('no-story avatar preserves profile fallback',page.evaluate('visits.length===3'))
 page.evaluate("""document.addEventListener('click',e=>{if(e.target.closest('#conversationAvatar')){e.preventDefault();e.stopImmediatePropagation();window.storyOpened=true}},{capture:true,once:true})""")
 page.locator('#conversationAvatar').click();check('story capture can intercept without opening profile',page.evaluate('storyOpened&&visits.length===3'))
 page.evaluate("document.querySelector('#app').classList.add('composer-fullscreen')")
 check('fullscreen composer hides identity',not page.locator('.chatAvatarDock').is_visible())
 page.evaluate("document.querySelector('#app').classList.remove('composer-fullscreen')")
 page.set_viewport_size({'width':390,'height':844});page.screenshot(path=str(out/f'header-{a.engine}.png'))
 page.evaluate("""()=>{window.contactState={sessionUserId:'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',sessionGeneration:1,conversationId:'cccccccc-cccc-4ccc-8ccc-cccccccccccc',screen:'conversation'};window.PablicusController={state:()=>contactState,subscribe:()=>()=>{},getServices:()=>null};window.contactCalls=[];}""")
 page.add_script_tag(content=(root/'contact-card.js').read_text())
 page.evaluate("""async()=>{const rows={select(){return this},eq(){return this},order(){return this},range:async()=>({data:[]})};window.contactTest=PablicusContactCard.create({client:{rpc:async()=>({data:{kind:'contact',profile:{id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',display_name:'Public name',username:'fixture'},personal:{first_name:'Личное имя'},conversation_id:contactState.conversationId}}),from:()=>rows},controller:PablicusController,getDialogs:()=>[],startCall:(id,kind)=>{contactCalls.push({id,kind});return false}});await contactTest.open(contactState.conversationId)}""")
 page.locator('[data-contact-call="audio"]').click();page.locator('[data-contact-call="video"]').click()
 check('profile audio and video target viewed conversation',page.evaluate("contactCalls.length===2&&contactCalls.every(c=>c.id===contactState.conversationId)&&contactCalls[0].kind==='audio'&&contactCalls[1].kind==='video'"))
 check('unavailable call keeps profile open',page.locator('#pablicusContactCard').evaluate('(n)=>n.open'))
 page.evaluate("contactState.sessionUserId='dddddddd-dddd-4ddd-8ddd-dddddddddddd'")
 page.locator('[data-contact-call="audio"]').click()
 check('old account profile cannot start call',page.evaluate('contactCalls.length===2'))
 page.add_script_tag(content=(root/'rich-message.js').read_text())
 page.evaluate("document.querySelector('#pablicusContactCard').close();document.querySelector('#app').hidden=false")
 for count in [1,2,3,4,5,7,10,12]:
  page.evaluate("""(count)=>{document.querySelector('#mediaFixture')?.remove();const row=document.createElement('article');row.id='mediaFixture';row.className='row';const bubble=document.createElement('div');bubble.className='bubble';const blocks=Array.from({length:count},(_,i)=>({id:'photo-'+i,type:i%2?'video':'image',path:'fixture/'+i,name:'fixture',width:600,height:800}));bubble.append(PablicusRichMessage.render({v:1,blocks},{inlineVideo:true,measurement:true,openMedia:(b,g)=>window.albumOpened={id:b.id,count:g?.items.length||1,index:g?.index||0}}));row.append(bubble);document.querySelector('#app>.stage').append(row)}""",count)
  box=page.locator('#mediaFixture>.bubble').bounding_box();appBox=page.locator('#app').bounding_box()
  check(str(count)+' media compact width',box['width']<appBox['width']*.8)
  check(str(count)+' attachments retained in order',page.locator('#mediaFixture [data-block-id]').evaluate_all('(nodes)=>nodes.every((n,i)=>n.dataset.blockId==="photo-"+i)&&nodes.length')==count)
  if count>1:
   check(str(count)+' joined grid tiles',page.locator('#mediaFixture .richMediaGallery').evaluate('(n)=>getComputedStyle(n).display==="grid"&&[...n.children].every(c=>getComputedStyle(c).borderRadius==="0px"&&c.getBoundingClientRect().height>0)'))
 page.locator('#mediaFixture').evaluate('(n)=>n.remove()')
 for w,h in [(600,900),(900,1600),(1600,900),(800,800),(200,1800)]:
  page.evaluate("""([w,h])=>{document.querySelector('#sourceFixture')?.remove();const row=document.createElement('article');row.id='sourceFixture';row.className='row';row.style.cssText='position:fixed;top:280px;left:0;width:350px;z-index:100;';const bubble=document.createElement('div');bubble.className='bubble';window.sourceUrl=URL.createObjectURL(new Blob([`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}"><rect width="100%" height="100%" fill="red"/><rect x="10" y="10" width="${w-20}" height="${h-20}" fill="blue"/></svg>`],{type:'image/svg+xml'}));bubble.append(PablicusRichMessage.render({v:1,blocks:[{id:'source-photo',type:'image',path:'fixture/source'}]},{mountRoot:document.querySelector('#app'),resolveUrl:()=>sourceUrl}));row.append(bubble);document.querySelector('#app>.stage').append(row)}""",[w,h])
  try:page.locator('#sourceFixture .richImageReady').wait_for()
  except Exception:
   print(page.locator('#sourceFixture').evaluate('(n)=>({html:n.outerHTML,box:n.getBoundingClientRect().toJSON(),image:n.querySelector("img")?.naturalWidth})'),flush=True)
   raise
  check(str(w)+'x'+str(h)+' decoded ratio recovered without metadata',page.locator('#sourceFixture .richMedia').evaluate('(n)=>Number(n.style.getPropertyValue("--rich-image-ratio"))')==w/h)
  check(str(w)+'x'+str(h)+' entire photo fits without cover crop',page.locator('#sourceFixture img').evaluate('(n)=>{const s=getComputedStyle(n),r=n.getBoundingClientRect(),p=n.parentElement.getBoundingClientRect();return n.naturalWidth>0&&s.objectFit==="contain"&&Math.abs(r.width/r.height-n.naturalWidth/n.naturalHeight)<.005&&Math.abs(r.width-p.width)<1&&Math.abs(r.height-p.height)<1&&r.height<=421}'))
  page.evaluate("document.querySelector('#sourceFixture').remove();URL.revokeObjectURL(sourceUrl)")
 browser.close()
(out/f'header-{a.engine}.json').write_text(json.dumps({'engine':a.engine,'checks':checks,'passed':len(checks)},ensure_ascii=False,indent=2))
print(json.dumps({'passed':len(checks),'checks':checks},ensure_ascii=False))
